// Per-workspace hosted legal pages (issue #184): privacy / terms / refund.
// Each page is either auto-generated by the LLM or written manually by the
// merchant, with the content stored here and rendered on the public page
// ({workspace}.jomform.com/privacy, /terms, /refund).
package dbstore

import (
	"context"
	"errors"
)

// LegalPageType enumerates the three hosted legal page kinds.
const (
	LegalPagePrivacy = "privacy"
	LegalPageTerms   = "terms"
	LegalPageRefund  = "refund"
)

// LegalPageMode is how a page's content was produced.
const (
	LegalModeAuto   = "auto"   // generated by the LLM
	LegalModeManual = "manual" // written by the merchant
)

// ErrLegalPageNotFound is returned when a workspace has no content for a page
// type (the public route 404s).
var ErrLegalPageNotFound = errors.New("legal page not set")

// LegalPage is one hosted legal page for a workspace.
type LegalPage struct {
	WorkspaceID string `json:"workspace_id"`
	PageType    string `json:"page_type"`
	Mode        string `json:"mode"`
	Content     string `json:"content"`
}

// LegalPage reads one legal page for a workspace. Returns ErrLegalPageNotFound
// when the page has no stored content (not set).
func (s *WorkspaceStore) LegalPage(ctx context.Context, workspaceID, pageType string) (*LegalPage, error) {
	p := &LegalPage{WorkspaceID: workspaceID, PageType: pageType}
	err := s.pool.QueryRow(ctx,
		`SELECT mode, content FROM workspace_legal_pages WHERE workspace_id=$1 AND page_type=$2`,
		workspaceID, pageType).Scan(&p.Mode, &p.Content)
	if err != nil {
		return nil, err
	}
	if p.Content == "" {
		return nil, ErrLegalPageNotFound
	}
	return p, nil
}

// LegalPages reads all three legal pages for a workspace (empty content when not
// set). Used by the settings UI to show current state.
func (s *WorkspaceStore) LegalPages(ctx context.Context, workspaceID string) (map[string]*LegalPage, error) {
	out := map[string]*LegalPage{
		LegalPagePrivacy: {WorkspaceID: workspaceID, PageType: LegalPagePrivacy, Mode: LegalModeManual},
		LegalPageTerms:   {WorkspaceID: workspaceID, PageType: LegalPageTerms, Mode: LegalModeManual},
		LegalPageRefund:  {WorkspaceID: workspaceID, PageType: LegalPageRefund, Mode: LegalModeManual},
	}
	rows, err := s.pool.Query(ctx,
		`SELECT page_type, mode, content FROM workspace_legal_pages WHERE workspace_id=$1`,
		workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var pt, mode, content string
		if err := rows.Scan(&pt, &mode, &content); err != nil {
			return nil, err
		}
		if p, ok := out[pt]; ok {
			p.Mode = mode
			p.Content = content
		}
	}
	return out, rows.Err()
}

// SaveLegalPage upserts one legal page's content + mode.
func (s *WorkspaceStore) SaveLegalPage(ctx context.Context, p *LegalPage) error {
	_, err := s.pool.Exec(ctx,
		`INSERT INTO workspace_legal_pages (workspace_id, page_type, mode, content, updated_at)
		 VALUES ($1,$2,$3,$4, now())
		 ON CONFLICT (workspace_id, page_type) DO UPDATE SET
		   mode=EXCLUDED.mode, content=EXCLUDED.content, updated_at=now()`,
		p.WorkspaceID, p.PageType, p.Mode, p.Content)
	return err
}
